// Demo: Materials Test Analyzer - public implementations survey
(function(){'use strict';
var DATA={"label": "Materials Test Analyzer - public implementations survey", "rows": [["SMILES", "75"], ["  SMILES ", "43"], ["Periodic table", "80"], ["Green chemistry", "27"], ["  Green chemistry ", "32"], ["Materials Project", "84"], ["The periodic table", "66"], ["  The periodic table ", "35"], ["", ""], ["SMILES", "42"]]};

var seen={},kept=[],droppedEmpty=0,droppedDup=0;
console.log('Cleaning '+DATA.rows.length+' rows ('+DATA.label+'):');
